from pathlib import Path
import json,base64
from build import META,OUT,ROOT

CSS='''*{box-sizing:border-box}body{margin:0;background:#F3F4F6;color:#172029;font-family:'Segoe UI','Microsoft YaHei',sans-serif;font-size:14px}button,select{font:inherit;cursor:pointer}a{color:inherit;text-decoration:none}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #5268BB;outline-offset:3px}.head{padding:28px 36px 20px;background:white;border-bottom:1px solid #DDE2E7}.top{display:flex;justify-content:space-between;align-items:center;gap:20px}.mark{font-size:13px;font-weight:600;color:#687383;margin-bottom:12px}h1{font-size:28px;letter-spacing:-.04em;font-weight:600;margin:0}.head p{margin:10px 0 0;color:#687383;font-size:12px;line-height:1.8;max-width:90ch}.button{display:inline-flex;align-items:center;justify-content:center;border:1px solid #D8DDE4;border-radius:6px;background:#fff;min-height:36px;padding:7px 13px;font-size:12px;gap:6px}.button:hover{background:#F0F3F6}.toolbar{padding:16px 36px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;background:#FAFBFC;border-bottom:1px solid #DDE2E7}.modes{display:flex;gap:4px;flex-wrap:wrap}.modes button{border:0;padding:9px 16px;border-radius:5px;background:transparent;color:#5B6674;font-size:12px;min-height:38px}.modes button.active{background:#233349;color:white}.controls{display:flex;gap:12px;align-items:center;font-size:12px;flex-wrap:wrap}select{border:1px solid #CED5DF;padding:8px;border-radius:5px;background:white;color:#283545;max-width:220px}.stage{padding:24px 36px 36px;display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}.stage.single{grid-template-columns:1fr;max-width:1600px;margin:auto}.tile{min-width:0;border:1px solid #D6DDE4;border-radius:10px;background:white;overflow:hidden}.tile-head{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:14px 18px;border-bottom:1px solid #DDE2E7}.tile-head h2{font-size:14px;font-weight:600;margin:0}.tile-head p{font-size:11px;color:#697786;margin:4px 0 0}.tile-head .links{display:flex;gap:6px;align-items:center}.tile-head .button{font-size:11px;padding:6px 10px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:8px}.viewport{width:100%;position:relative;overflow:hidden;background:#E9EDF1}.frame{border:0;display:block;transform-origin:top left;background:white;position:absolute;top:0;left:0}.tile-foot{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px 18px;font-size:10px;color:#637081;border-top:1px solid #DDE2E7}.hint{padding:0 36px 30px;color:#677381;font-size:12px;line-height:1.8}.phone .viewport{max-width:430px;margin:0 auto}.phone .tile{background:#E9EDF1}.phone .tile-head,.phone .tile-foot{background:#fff}dialog{width:min(850px,calc(100vw - 32px));max-height:85dvh;border:1px solid #D2D9E2;border-radius:12px;padding:0;color:#172029;background:#fff}dialog::backdrop{background:#18293D99}.dialog-head{padding:20px 24px;border-bottom:1px solid #DFE3E9;display:flex;align-items:center;justify-content:space-between}.dialog-head h2{font-size:18px;margin:0}.dialog-content{padding:24px;font-size:13px;line-height:1.9}.dialog-content pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;background:#F4F6F8;padding:18px;border-radius:6px}.dialog-content a{text-decoration:underline;text-underline-offset:3px;color:#344E85}.subtle{color:#637081}.hidden{display:none!important}.mobile-label{font-size:11px;color:#617083}@media(max-width:760px){.head{padding:22px 18px}.top{display:block}.top .button{margin-top:14px}h1{font-size:25px}.toolbar{padding:14px 18px}.stage{padding:18px;gap:20px;grid-template-columns:1fr}.hint{padding:0 18px 24px}.controls{width:100%}.controls select{max-width:165px}.tile-head{padding:12px}.tile-head .links{gap:4px}.tile-head .button{padding:6px 8px}.tile-head h2{font-size:12px}.tile-head p{font-size:10px}.modes button{padding:9px 12px;min-height:44px}.button{min-height:40px}.tile-foot{padding:10px 12px;flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}'''
items=[]
prompts=(ROOT/'prompts.txt').read_text(encoding='utf-8')
decisions=(ROOT/'design-decisions.txt').read_text(encoding='utf-8')
sources=[
 ('Impeccable v4.5.2','https://github.com/pbakaus/impeccable/tree/d631a8827f99414d2b6daba4ef08b7f8701751d7/.agents/skills/impeccable'),
 ('UI UX Pro Max','https://github.com/nextlevelbuilder/ui-ux-pro-max-skill/tree/67803eac81607188194aea9842a723b89326d90d/.claude/skills/ui-ux-pro-max'),
 ('Taste / minimalist-ui','https://github.com/Leonxlnx/taste-skill/tree/717446e07a78d4e6d7918b1fde1a263378eebac9/skills/minimalist-skill'),
 ('Anthropic frontend-design','https://github.com/anthropics/skills/tree/41bbe19d1a1a7eaab5e7bb9050a417e5c6cffc8f/skills/frontend-design'),
]
for m in META:
    items.append({**m,'html':base64.b64encode((OUT/m['file']).read_bytes()).decode()})
DATA=json.dumps({'items':items,'prompts':prompts,'decisions':decisions,'sources':sources},ensure_ascii=False).replace('</',r'<\/')
JS=r'''
const DATA=__DATA__;
let mode='overview',single=0,device=1440,left=0,right=1;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const decode=s=>new TextDecoder().decode(Uint8Array.from(atob(s),c=>c.charCodeAt(0)));
function saveHTML(i){const item=DATA.items[i],blob=new Blob([decode(item.html)],{type:'text/html;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=item.file;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function openHTML(i){const tab=window.open('about:blank','_blank');if(tab){tab.document.open();tab.document.write(decode(DATA.items[i].html));tab.document.close()}}
function render(){const idx=mode==='overview'?[0,1,2,3]:mode==='single'?[single]:[left,right];$('#stage').className='stage '+(mode==='single'?'single ':'')+(device===390?'phone':'');$('#single-control').classList.toggle('hidden',mode!=='single');$('#pair-control').classList.toggle('hidden',mode!=='pair');$('#stage').innerHTML=idx.map(i=>{const m=DATA.items[i];return `<section class="tile"><div class="tile-head"><div><h2><span class="dot" style="background:${m.color}"></span>${esc(m.title)}</h2><p>${esc(m.subtitle)} / ${esc(m.tag)}</p></div><div class="links"><button class="button" data-open="${i}" aria-label="单独打开 ${esc(m.title)}">打开</button><button class="button" data-download="${i}" aria-label="下载 ${esc(m.title)} HTML">下载 HTML</button></div></div><div class="viewport"><iframe class="frame" data-index="${i}" title="${esc(m.title)} 交互 Demo"></iframe></div><div class="tile-foot"><span>${device===390?'390 × 844 手机视口':device===768?'768 × 1024 平板视口':'1440 × 960 桌面视口'} · 同尺寸缩放</span><button class="button" data-focus="${i}">放大比较</button></div></section>`}).join('');$$('iframe').forEach(f=>f.srcdoc=decode(DATA.items[+f.dataset.index].html));fit();$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode)})}
function fit(){$$('.viewport').forEach(v=>{const frame=v.querySelector('iframe'),h=device===390?844:device===768?1024:960,scale=Math.min(v.clientWidth/device,1);frame.style.width=device+'px';frame.style.height=h+'px';frame.style.transform='scale('+scale+')';frame.style.left=Math.max(0,(v.clientWidth-device*scale)/2)+'px';v.style.height=(h*scale)+'px'})}
function notes(which){$('#notes-title').textContent=which==='prompts'?'提示词与比较方法':'设计依据与来源';const links=DATA.sources.map(([n,u])=>`<li><a href="${u}" target="_blank" rel="noopener">${esc(n)}</a></li>`).join('');$('#notes-body').innerHTML=(which==='decisions'?'<ul>'+links+'</ul>':'')+'<pre>'+esc(DATA[which])+'</pre>';$('#notes').showModal()}
document.addEventListener('click',e=>{const m=e.target.closest('[data-mode]');if(m){mode=m.dataset.mode;render()}const f=e.target.closest('[data-focus]');if(f){single=+f.dataset.focus;mode='single';$('#single-select').value=single;render();window.scrollTo({top:0,behavior:'smooth'})}const o=e.target.closest('[data-open]');if(o)openHTML(+o.dataset.open);const d=e.target.closest('[data-download]');if(d)saveHTML(+d.dataset.download);const n=e.target.closest('[data-notes]');if(n)notes(n.dataset.notes)});
$('#device').onchange=e=>{device=+e.target.value;render()};$('#single-select').onchange=e=>{single=+e.target.value;render()};$('#left-select').onchange=e=>{left=+e.target.value;render()};$('#right-select').onchange=e=>{right=+e.target.value;render()};$('#close-notes').onclick=()=>$('#notes').close();new ResizeObserver(fit).observe($('#stage'));render();
'''.replace('__DATA__',DATA)
options=''.join(f'<option value="{i}">{m["title"]}</option>' for i,m in enumerate(META))
HTML='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quant Studio · 四种 UI 设计对比</title><style>'''+CSS+'''</style></head><body><header class="head"><div class="mark">Quant Studio / 设计探索</div><div class="top"><h1>四种设计，同一个工作台。</h1><div><button class="button" data-notes="prompts">提示词与比较方法</button> <button class="button" data-notes="decisions">设计依据与来源</button></div></div><p>相同的研究内容与交互，不同的布局和视觉选择。先看整体，再放大操作；保存方案、模拟运行、筛选任务与查看报告都可以试。</p></header><div class="toolbar"><div class="modes" aria-label="比较方式"><button class="active" data-mode="overview" aria-pressed="true">四版总览</button><button data-mode="pair" aria-pressed="false">左右对比</button><button data-mode="single" aria-pressed="false">单版体验</button></div><div class="controls"><div id="single-control" class="hidden"><label for="single-select">方案 </label><select id="single-select">'''+options+'''</select></div><div id="pair-control" class="hidden"><select id="left-select" aria-label="左侧设计">'''+options+'''</select> <span>对比</span> <select id="right-select" aria-label="右侧设计">'''+options.replace('<option value="1">','<option value="1" selected>')+'''</select></div><label for="device">视口</label><select id="device"><option value="1440">桌面 1440px</option><option value="768">平板 768px</option><option value="390">手机 390px</option></select></div></div><main class="stage" id="stage"></main><div class="hint">每个页面均为离线 HTML，使用固定合成数据，不调用真实研究服务。四版由同一模型分别遵循技能规则实现，共享行为代码；这是设计方向比较，不是独立模型测试或技能能力排名。<br>Taste 版使用同仓库的 minimalist-ui 分支。浏览器本地保存彼此隔离；文件环境不允许存储时保留在当前页面会话。</div><dialog id="notes" aria-labelledby="notes-title"><div class="dialog-head"><h2 id="notes-title">说明</h2><button class="button" id="close-notes">关闭</button></div><div class="dialog-content" id="notes-body"></div></dialog><script>'''+JS+'''</script></body></html>'''
(OUT/'index.html').write_text(HTML,encoding='utf-8')
print('Built self-contained comparison index',len(HTML.encode('utf-8')),'bytes')
